    if mode is not None:
        output.append(mode)
    if bookmarks is not None:
        output.append(bookmarks)
    if metadata is not None:
        output.append(metadata)
    if timeout is not None:
        output.append(PackStream.MessageType.TTL)
        output.append(timeout)
    if db is not None:
        output.append(PackStream.MessageType.DB)
        output.append(db)
    if imp_user is not None:
        output.append(PackStream.MessageType.IDENTITY)
        output.append(imp_user)
    if dehydration_hooks is not None or hydration_hooks is not None:
        output.append(PackStream.MessageType.TYPES)
        if dehydration_hooks is not None:
            output.append(dehydration_hooks)
        if hydration_hooks is not None:
            output.append(hydration_hooks)

    response = Response(self, output)
