def _shuffle(seq: Sequence[str], result: list[str]):
    if len(seq) == 0:
        return result
    r = random.random()
    if r < 0.5:
        result.append(seq[0])
        return _shuffle(seq[1:], result)
    else:
        result.append(seq[-1])
        return _shuffle(seq[:-1], result)
