def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = _LRUCache(maxsize, ttl, timer, typed)
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            item = _normalize_key(args, kwargs, typed, cache.item_type)
            try:
                result = cache[item]
            except KeyError:
                result = func(*args, **kwargs)
                cache[item] = result
            return result
        return wrapper
    return decorator

class _LRUCache:
    def __init__(self, maxsize, ttl, timer, typed):
        self.maxsize = maxsize
        self.ttl = ttl
        self.timer = timer
        self.typed = typed
        self.item_type = tuple if typed else object
        self._cache = collections.OrderedDict()

    def __getitem__(self, key):
        value = self._cache[key]
        try:
            ttl = value[1]
            if ttl > self.ttl:
                raise KeyError
            return value
        except IndexError:
            raise KeyError

    def __setitem__(self, key, value):
        self._cache[key] = (value, self.timer())
        if len(self._cache) > self.maxsize:
            self._cache.popitem(False)

    def __delitem__(self, key):
        del self._cache[key]

    def popitem(self, last=True):
        if last:
            return self._cache.popitem()
        else:
            return self._cache.popleft()

def _normalize_key(args, kwargs, typed, key_type):
    if typed:
        if not (isinstance(args, key_type)):
            raise TypeError('Expected {} arguments, got {}'.format(key_type, args))
        return args
    else:
        return _HashableKey(args, kwargs)

class _HashableKey:
    def __init__(self, args, kwargs):
        self.args = args
        self.kwargs = kwargs

    def __hash__(self):
        return hash(self.args + tuple(self.kwargs.items()))

    def __eq__(self, other):
        return self.args == other.args and self.kwargs == other.kwargs
