def mru_cache( cached_fn, maxsize=128, typed=False ):
    memo = {}
    hits = 0
    misses = 0
    full = False
    def build_key( args, typed ):
        if typed:
            return tuple( map( type, args ) )
        else:
            return args
    def cachable( fn ):
        nonlocal hits, misses
        def cached( *args, **kwargs ):
            key = build_key( args, typed )
            if key in memo:
                hits += 1
                return memo[key]
            else:
                misses += 1
                result = fn( *args, **kwargs )
                memo[key] = result
                if len( memo ) > maxsize and not full:
                    evict()
                return result
        return cached
    def evict():
        nonlocal full
        if key := min( memo, key = lambda k: memo[k][1] ):
            del memo[key]
            full = False
    return cachable( cached_fn )
