def lfu_cache(maxsize=128, typed=False):
    """Decorator that wraps a function with a memoizing callable that saves up to `maxsize` results based on a Least Frequently Used (LFU) algorithm.

    Args:
        maxsize (int): Maximum number of results to cache.
        typed (bool): If True, cache separate entries for each distinct type of argument.

    Returns:
        function: The decorated function, with memoized results based on LFU algorithm.

    """

    def generate_memoized_function(func):
        cache = {}
        access = {}
        freq = {}
        hits = miss = 0

        def wrapper(*args, **kwargs):
            nonlocal hits, miss
            key = hash((args, tuple(kwargs.items())))
            if typed:
                key += (type(args[0]), *[type(arg) for arg in args[1:]])
            try:
                cached_value = cache[key]
                access[key] = time.time()
                hits += 1
            except KeyError:
                miss += 1
                freq[key] = 1
                return func(*args, **kwargs)

        def cache_info():
            return {
                "hits": hits,
                "misses": miss,
                "maxsize": cache.maxsize,
                "currsize": len(cache),
            }

        return wrapper

    return generate_memoized_function

