    class Cache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.data = {}
            self.frequencies = {}
            self.most_frequent = None
            self.least_frequent = None

        def __call__(self, *args, **kwargs):
            key = self.make_key(args, kwargs)
            try:
                return self.data[key]
            except KeyError:
                self.add_or_update(key)
                return self.data[key]

