            self.data[key] = value
            self.frequencies[key] = 1
            if self.most_frequent is None or self.most_frequent == key:
                self.most_frequent = key
            if self.least_frequent is None or self.least_frequent == key:
                self.least_frequent = key

        def make_key(self, args, kwargs):
            if self.typed:
                return (type(arg) for arg in args) + tuple(sorted(kwargs.items()))
            return args + tuple(sorted(kwargs.items()))

    return Cache
