        if output is None:
            return [Declaration(*tup) for tup in sequence]
        else:
            return [Declaration(*tup) for tup in sequence]

    # The input is a list of something else, expand it
    flat_seq = []
    for item in sequence:
        if isinstance(item, Declaration):
            flat_seq.append(item)
        elif isinstance(item, tuple):
            flat_seq.append(tuple(item))
        elif isinstance(item, (list, set, Sequence)):
            for sub_item in item:
                flat_seq.append(sub_item)
        else:
            raise TypeError(f"Invalid input type {type(item)}")

    if output is None:
        return flat_seq
    else:
        return Sequence(flat_seq)
