        while previous_version.version_id != 0:
            if not previous_version.is_consistent:
                raise ValueError("Inventory is not consistent with previous version")
            previous_version = previous_version.get_previous_version()

    # Check that the current inventory is consistent with the prior version
    if prior.version_id > 0:
        if not prior.version_dict == self.version_dict:
