    # check that fixity block is a list
    if not isinstance(fixity, list):
        raise TypeError("expected 'fixity' to be a list")

    # check that list items are dicts
    for item in fixity:
        if not isinstance(item, dict):
            raise TypeError("expected each item in 'fixity' to be a dict")

    # check that each dict has 'pid' and 'hash' keys
    for item in fixity:
        if "pid" not in item or "hash" not in item:
