def _fromutc(self, dt):
    if dt.tzinfo is None:
        raise ValueError("Parameter 'dt' must be a timezone-aware datetime object.")

    # Determine if the given datetime is in a "fold" state
    if dt.fold:
        raise ValueError("The given datetime object is in a 'fold' state. It is not possible to determine its timezone-aware datetime in a new timezone.")

    # Convert the given datetime to its equivalent in a new timezone
    return dt.astimezone(self.tz)

def _fromutc(self, dt):
    if not dt.tzinfo:
        raise ValueError("dt is not a timezone-aware datetime")

    new_tz = self.tzinfo
    offset = new_tz.utcoffset(dt)
    new_dt = dt.astimezone(new_tz)

    if new_dt.tzinfo.dst(new_dt) is None and offset == timedelta(0):
        if new_tz != utc:
            raise ValueError(f"{dt} is ambigous and cannot be converted to a timezone-aware datetime")

    return new_dt

def normalized(self):
