def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Args:
        validate_objects (bool, optional): Whether to validate object metadata. Defaults to True.
        check_digests (bool, optional): Whether to check object digests. Defaults to True.
        show_warnings (bool, optional): Whether to show warnings. Defaults to False.

    Returns:
        tuple(int, int): Number of objects checked and number of valid objects found.
    """
    num_objects = 0
    good_objects = 0

    for root in self.roots:
        for obj in root.get_children(recursive=True):
            num_objects += 1
            if not obj.validate_object():
                if show_warnings:
                    print(f"Warning: invalid object {obj.name} at {obj.location}")
            else:
                good_objects += 1

    if check_digests:
        for obj in self.get_all_objects():
            if not obj.validate_digest():
                if show_warnings:
                    print(f"Warning: invalid digest for object {obj.name} at {obj.location}")

    return num_objects, good_objects
