def determineMetaclass(bases, explicit_mc=None):
    # If explicit metaclass is specified, use it
    if explicit_mc is not None:
        return explicit_mc

    # If there is only one base, use its metaclass
    if len(bases) == 1:
        return type(bases[0])

    # If there is more than one base, use the most derived metaclass
    metaclasses = {type(base) for base in bases}
    derived_metaclass = max(metaclasses, key=lambda mc: mc.mro().index(mc))
    return derived_metaclass

