    dt_parts = dt_str.split("T")
    date_part, time_part = dt_parts[0], dt_parts[1]

    if len(date_part) == 4:
        year, month, day = date_part[:4], "01", "01"
    elif len(date_part) == 6:
        year, month, day = date_part[:4], date_part[4:6], "01"
    elif len(date_part) == 8:
        year, month, day = date_part[:4], date_part[4:6], date_part[6:8]
    else:
