    if time_part == "":
        hour, minute, second = "00", "00", "00"
    else:
        hour, minute, second = time_part[:2], time_part[2:4], time_part[4:]

    return datetime.datetime(int(year), int(month), int(day), int(hour), int(minute), int(second))

