def parse(timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    try:
        if default is not None and isinstance(default, datetime.datetime):
            dt = default
        else:
            dt = datetime.datetime.now()

        date = dt.date()
        time = None

        # Try to extract date and time from input string
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y%m%d %H:%M:%S", "%Y-%m-%d", "%Y%m%d"):
            try:
                date = datetime.datetime.strptime(timestr, fmt).date()
                time = datetime.datetime.strptime(timestr, fmt).time()
                break
            except ValueError:
                pass

        # If time was not extracted, use the default or current time
        if time is None:
            if default is not None and isinstance(default, datetime.time):
                time = default
            else:
                time = datetime.datetime.now().time()

        # Reconstruct datetime object
        dt = datetime.datetime.combine(date, time)

        # Truncate seconds and microseconds to 0
        dt = dt.replace(second=0, microsecond=0)

        # Handle time zone offsets
        if not ignoretz:
            if tzinfos:
                # Try to map time zone names to their respective offsets or tzinfo objects
                for i in range(len(timestr)-1, -1, -1):
                    curr_char = timestr[i].lower()
                    if curr_char in tzinfos:
                        tzinfo = tzinfos[curr_char]
                        if isinstance(tzinfo, datetime.tzinfo):
                            dt = dt.astimezone(tzinfo)
                        else:
                            dt = dt.replace(tzinfo=datetime.timezone(dtacore.Timedelta(seconds=tzinfo)))
                        break
            else:
                # Parse for ISO 8601 time zone specifier
                m = re.search(r"\+0000|\+00:00|\+00", timestr)
                if m:
                    tz = datetime.timezone.utc
                    dt = dt.astimezone(tz)

        return dt
    except (TypeError, OverflowError, ValueError, ParserError):
        raise
